<template><div class="sf-stepper"><span :id="id">{{ label }}</span><div><button type="button" class="sf-icon-button" :aria-label="'Decrease '+label" :disabled="disabled||value<=min" @click="$emit('input',Math.max(min,value-step))"><sf-icon name="minus" :size="18"/></button><output :aria-labelledby="id" aria-live="polite">{{ value }}</output><button type="button" class="sf-icon-button" :aria-label="'Increase '+label" :disabled="disabled||value>=max" @click="$emit('input',Math.min(max,value+step))"><sf-icon name="plus" :size="18"/></button></div></div></template>
<script>import SfIcon from './SfIcon';let sequence=0;export default {name:'SfStepper',components:{SfIcon},props:{value:{type:Number,required:true},label:{type:String,required:true},min:{type:Number,default:0},max:{type:Number,default:10},step:{type:Number,default:1},disabled:Boolean},data(){return {id:'sf-stepper-'+(++sequence)}}}</script>
